    const fb = document.getElementById(id+'-fb');
    if (chosen === correct) {
      el.classList.add('correct');
      fb.textContent = '✓ ' + lcFeedback[id][correct];
      fb.className = 'lc-fb show correct';
      lcScore += 2;
    } else {
