// ── PART 1: QUIZ & SCORING IIFE ──
(function(){
  let lcScore = 0;
  const lcAnswered = {};

  const lcFeedback = {
    mcq1: { D: 'At surface r = R, at 2R field is g_surface/4, so surface field = 4g.' },
    mcq2: { B: 'Weight = m × g = 50 × 1.6 = 80 N.' },
    mcq3: { A: 'r = R + 3R = 4R from centre. g ∝ 1/r² → factor 1/16.' },
    mcq4: { B: 'For r ≥ R, g = GM/r², a decreasing inverse‑square curve.' }
  };

  window.lcMCQ = function(id, el, chosen, correct) {
    if (lcAnswered[id]) return;
    lcAnswered[id] = true;
    const block = document.getElementById(id);
    block.querySelectorAll('.lc-opt').forEach(o => o.classList.add('disabled'));
    const fb = document.getElementById(id+'-fb');
    if (chosen === correct) {
      el.classList.add('correct');
      fb.textContent = '✓ ' + lcFeedback[id][correct];
      fb.className = 'lc-fb show correct';
      lcScore += 2;
    } else {
      el.classList.add('wrong');
      block.querySelectorAll('.lc-opt').forEach(o => {
        if (o.querySelector('.lc-opt-l').textContent === correct) o.classList.add('correct');
      });
      fb.textContent = '✗ Incorrect. Correct: ' + correct + '. ' + lcFeedback[id][correct];
      fb.className = 'lc-fb show wrong';
    }
    document.getElementById('lc-score-display').textContent = lcScore;
  };

  window.lcFITB = function() {
    const ans = { lf1:'force', lf2:'mass', lf3:'N/kg' };
    let correct = 0, total = Object.keys(ans).length;
    Object.keys(ans).forEach(id => {
      const el = document.getElementById(id);
      const val = el.value.trim().toLowerCase();
      const ok = val === ans[id] || (id==='lf3' && val === 'n/kg');
      el.classList.toggle('correct', ok);
      el.classList.toggle('wrong', !ok);
      if (ok) correct++;
    });
    const res = document.getElementById('lc-fitb-result');
    res.style.display = 'block';
    if (correct === total) {
      res.style.color = 'var(--green)';
      res.textContent = '✓ All correct! (+2 pts)';
      lcScore += 2;
      document.getElementById('lc-score-display').textContent = lcScore;
    } else {
      res.style.color = 'var(--red)';
      res.textContent = correct + '/' + total + ' correct. Answers: force · mass · N/kg';
    }
  };

  window.lcToggleModel = function(btn) {
    const ma = btn.nextElementSibling;
    ma.classList.toggle('show');
    btn.textContent = ma.classList.contains('show') ? 'Hide model answer' : 'Show model answer';
  };
})();

// ── PART 2: CANVAS DRAWING (theme-aware) ──
function getThemeColor(varName) {
  return getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
}

// Lab 1: Planet builder
const planetCanvas = document.getElementById('planetCanvas');
const ctxPlanet = planetCanvas.getContext('2d');
planetCanvas.width = 600; planetCanvas.height = 220;

function drawPlanet(M, R) {
  const w = planetCanvas.width, h = planetCanvas.height;
  ctxPlanet.fillStyle = getThemeColor('--surface3') || '#e8e6e2';
  ctxPlanet.fillRect(0, 0, w, h);
  // Draw axes
  ctxPlanet.beginPath();
  ctxPlanet.strokeStyle = getThemeColor('--border-2') || '#aaa';
  ctxPlanet.lineWidth = 1;
  ctxPlanet.moveTo(40, h-30);
  ctxPlanet.lineTo(w-20, h-30);
  ctxPlanet.moveTo(40, 20);
  ctxPlanet.lineTo(40, h-30);
  ctxPlanet.stroke();
  ctxPlanet.fillStyle = getThemeColor('--text-muted') || '#666';
  ctxPlanet.font = "10px sans-serif";
  ctxPlanet.fillText("r (×10⁶ m)", w-50, h-15);
  ctxPlanet.fillText("g (N/kg)", 10, 30);
  // Compute g values
  const Gval = 6.67e-11;
  let max_g = (Gval * M * 1e24) / ( (R*1e6)**2 );
  // Plot from r = R to 2R (in m)
  const r0 = R * 1e6;
  const xScale = (w-80) / (r0);  // from r0 to 2r0 -> x range
  for (let x=0; x<=w-80; x++) {
    let r = r0 + (x/(w-80)) * r0;
    let g = (Gval * M * 1e24) / (r*r);
    let px = 40 + x;
    let py = h-30 - (g/max_g)*(h-50);
    if (x===0) ctxPlanet.beginPath(), ctxPlanet.moveTo(px, py);
    else ctxPlanet.lineTo(px, py);
  }
  ctxPlanet.strokeStyle = getThemeColor('--accent') || '#0077be';
  ctxPlanet.lineWidth = 2;
  ctxPlanet.stroke();
  ctxPlanet.fillStyle = getThemeColor('--accent') || '#0077be';
  ctxPlanet.fillText("g = GM/r²", w-100, 50);
}

function updatePlanet() {
  let M = parseFloat(document.getElementById('massSlider').value);
  let R = parseFloat(document.getElementById('radiusSlider').value);
  document.getElementById('massVal').innerText = M;
  document.getElementById('radiusVal').innerText = R;
  const g = (6.67e-11 * M * 1e24) / ( (R*1e6)**2 );
  document.getElementById('gValue').innerText = g.toFixed(2);
  drawPlanet(M, R);
}
document.getElementById('massSlider').addEventListener('input', updatePlanet);
document.getElementById('radiusSlider').addEventListener('input', updatePlanet);
updatePlanet();

// Lab 2: Inverse‑square journey
const orbitCanvas = document.getElementById('orbitCanvas');
const ctxOrbit = orbitCanvas.getContext('2d');
orbitCanvas.width = 600; orbitCanvas.height = 220;

function drawOrbit(ratio) {
  const w = orbitCanvas.width, h = orbitCanvas.height;
  ctxOrbit.fillStyle = getThemeColor('--surface3') || '#e8e6e2';
  ctxOrbit.fillRect(0, 0, w, h);
  // axes
  ctxOrbit.beginPath();
  ctxOrbit.strokeStyle = getThemeColor('--border-2') || '#aaa';
  ctxOrbit.moveTo(40, h-30);
  ctxOrbit.lineTo(w-20, h-30);
  ctxOrbit.moveTo(40, 20);
  ctxOrbit.lineTo(40, h-30);
  ctxOrbit.stroke();
  ctxOrbit.fillStyle = getThemeColor('--text-muted') || '#666';
  ctxOrbit.fillText("r / R_🜨", w-50, h-15);
  ctxOrbit.fillText("g (N/kg)", 10, 30);
  // g values for Earth: g_surface = 9.81
  const maxX = 5;
  for (let i=0; i<=w-80; i++) {
    let rRatio = (i/(w-80)) * maxX;
    if (rRatio < 1) rRatio = 1;
    let g = 9.81 / (rRatio*rRatio);
    let px = 40 + i;
    let py = h-30 - (g/9.81)*(h-50);
    if (i===0) ctxOrbit.beginPath(), ctxOrbit.moveTo(px, py);
    else ctxOrbit.lineTo(px, py);
  }
  ctxOrbit.strokeStyle = getThemeColor('--green') || '#2c7a4d';
  ctxOrbit.lineWidth = 2.5;
  ctxOrbit.stroke();
  // mark current point
  let gCurr = 9.81 / (ratio*ratio);
  let pxCurr = 40 + (ratio/maxX)*(w-80);
  let pyCurr = h-30 - (gCurr/9.81)*(h-50);
  ctxOrbit.beginPath();
  ctxOrbit.fillStyle = getThemeColor('--gold') || '#d4af37';
  ctxOrbit.arc(pxCurr, pyCurr, 5, 0, 2*Math.PI);
  ctxOrbit.fill();
  ctxOrbit.fillStyle = getThemeColor('--text') || '#000';
  ctxOrbit.fillText("You are here", pxCurr+5, pyCurr-5);
}

function updateOrbit() {
  let ratio = parseFloat(document.getElementById('heightSlider').value);
  document.getElementById('rRatio').innerText = ratio.toFixed(2);
  let g = 9.81 / (ratio*ratio);
  document.getElementById('gOrbit').innerText = g.toFixed(2);
  drawOrbit(ratio);
}
document.getElementById('heightSlider').addEventListener('input', updateOrbit);
updateOrbit();

window.drawPlanet = drawPlanet;
window.drawOrbit = drawOrbit;

// KaTeX auto-render
document.addEventListener('DOMContentLoaded', function() {
  if (typeof renderMathInElement !== 'undefined') {
    renderMathInElement(document.body, {
      delimiters: [
        { left: '$$', right: '$$', display: true },
        { left: '\\(', right: '\\)', display: false }
      ],
      throwOnError: false
    });
  }
});
</script>
